import{_ as r}from"./chunks/ptz-camera.BFf5oNXY.js";import{_ as e,a as i,b as s,c,d as t,e as l,f as o}from"./chunks/rbq10-charger.7uvTks7d.js";import{_ as d}from"./chunks/battery.DVQhiztz.js";import{_ as n}from"./chunks/docking-station.MKYdxThc.js";import{_ as h,o as p,c as m,a5 as g}from"./chunks/framework.D47SInms.js";const C=JSON.parse('{"title":"액세서리","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/product-descriptions/accessories.md","filePath":"ko/manual/product-descriptions/accessories.md","lastUpdated":1791600043000}'),b={name:"ko/manual/product-descriptions/accessories.md"};function u(f,a,v,_,q,y){return p(),m("div",null,[...a[0]||(a[0]=[g('<h1 id="액세서리" tabindex="-1">액세서리 <a class="header-anchor" href="#액세서리" aria-label="Permalink to &quot;액세서리&quot;">​</a></h1><p>RBQ는 현장 임무와 개발 목적에 맞게 로봇의 기능을 확장할 수 있는 다양한 선택형 액세서리를 지원합니다. 센싱, 연산·통신, 전원·충전 항목을 운용 목적에 따라 구성할 수 있습니다.</p><h2 id="sensing" tabindex="-1">센싱 <a class="header-anchor" href="#sensing" aria-label="Permalink to &quot;센싱 {#sensing}&quot;">​</a></h2><div class="rbq-card-grid"><div class="rbq-card"><img src="'+r+'" alt=""><h3 id="ptz-camera">PTZ Camera<a class="header-anchor" href="#ptz-camera" aria-label="PTZ Camera 링크"></a></h3><p>RBQ 본체에 장착하는 Pan-Tilt-Zoom 카메라입니다. 원격으로 패닝·틸팅·줌 제어가 가능하며, 고해상도 영상 스트리밍을 통해 감시 및 정찰 임무에 활용합니다. GUI와 API에서 모두 제어할 수 있습니다.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/related-products/ptz-camera">상세 사양 →</a></div><div class="rbq-card"><img src="'+e+'" alt=""><h3 id="lidar-mid-360">LIDAR (mid-360)<a class="header-anchor" href="#lidar-mid-360" aria-label="LIDAR (mid-360) 링크"></a></h3><p>Livox MID-360은 반구형 시야(360° × 59°)를 제공하는 소형 3D LiDAR입니다. 장애물 탐지와 자율 내비게이션에 활용되며, 이더넷으로 연결됩니다.</p><p><strong>MID-360S</strong>는 Livox의 차세대 모델입니다. 수평 360° · 수직 −7°~52° 시야에 40 m(10% 반사율) 탐지 거리, 초당 20만 포인트를 제공합니다. RBQ에는 <strong>수직축 기준 90° 돌려 장착</strong>하므로 좌표계가 MID-360과 다릅니다 — <a href="/RBQ/nightly/ko/manual/hardware/coordinate-frames#mid-360s">변환 행렬</a>을 확인하세요.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/related-products/lidar#mid-360">상세 사양 →</a></div><div class="rbq-card"><img src="'+i+'" alt=""><h3 id="lidar-os1-32">LIDAR (OS1-32)<a class="header-anchor" href="#lidar-os1-32" aria-label="LIDAR (OS1-32) 링크"></a></h3><p>Ouster OS1-32는 32채널 360° 회전형 LiDAR로, 광역 3D 매핑에 적합한 고밀도 포인트 클라우드를 제공합니다.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/related-products/lidar#os1-32">상세 사양 →</a></div></div><h2 id="compute-connectivity" tabindex="-1">연산 · 통신 <a class="header-anchor" href="#compute-connectivity" aria-label="Permalink to &quot;연산 · 통신 {#compute-connectivity}&quot;">​</a></h2><div class="rbq-card-grid"><div class="rbq-card"><img src="'+s+'" alt=""><h3 id="user-pc-module">User-PC Module<a class="header-anchor" href="#user-pc-module" aria-label="User-PC Module 링크"></a></h3><p>RBQ 페이로드 베이 내부에 장착하는 임베디드 연산 보드입니다. 사용자 애플리케이션, AI 추론, 커스텀 센서 처리 등을 로봇 내부에서 직접 실행할 수 있으며, 다양한 I/O 인터페이스를 통해 센서와 연결됩니다.</p><p>제공 옵션:</p><ul><li><strong>UP Xtreme i12</strong> — Intel Core i7 (12세대)</li><li><strong>UP Xtreme i14</strong> — Intel Core i7 (14세대)</li><li><strong>NVIDIA Jetson AGX Orin</strong> — AI 추론 워크로드용</li></ul><p>이 밖의 PC 사양이 필요한 경우 <a href="/RBQ/nightly/ko/manual/support/">문의</a>해 주세요.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/interface/network#onboard-pcs-and-ip-addresses">네트워크 · IP →</a></div><div class="rbq-card"><img src="'+c+'" alt=""><h3 id="hub-module">Hub Module<a class="header-anchor" href="#hub-module" aria-label="Hub Module 링크"></a></h3><p>사용 가능한 <code>12V-LAN</code> 포트 수를 늘려주는 인터페이스 허브입니다. 여러 센서를 동시에 연결해야 하는 페이로드 구성에서 배선을 단순화합니다.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/interface/external-port">외부 포트 →</a></div><div class="rbq-card"><img src="'+t+'" alt=""><h3 id="wifi-lte-gps-module">Wifi Module / LTE/GPS Module<a class="header-anchor" href="#wifi-lte-gps-module" aria-label="Wifi Module / LTE/GPS Module 링크"></a></h3><p>원격 운용을 위한 무선 통신 모듈입니다. WiFi 모듈은 근거리 고대역폭 통신을 지원하고, LTE/GPS 모듈은 광역 셀룰러 연결과 위치 측위 기능을 함께 제공합니다.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/interface/network">네트워크 →</a></div></div><h2 id="power-charging" tabindex="-1">전원 · 충전 <a class="header-anchor" href="#power-charging" aria-label="Permalink to &quot;전원 · 충전 {#power-charging}&quot;">​</a></h2><div class="rbq-card-grid"><div class="rbq-card"><img src="'+d+'" alt=""><h3 id="battery">Battery<a class="header-anchor" href="#battery" aria-label="Battery 링크"></a></h3><p>RBQ에 사용되는 분리형 배터리입니다. 장시간 연속 운용 시 배터리 교체 후 운용할 수 있습니다.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/related-products/battery">상세 사양 →</a></div><div class="rbq-card"><img src="'+l+'" alt=""><h3 id="battery-charging-tray">Battery Charging Tray<a class="header-anchor" href="#battery-charging-tray" aria-label="Battery Charging Tray 링크"></a></h3><p>배터리 팩을 로봇에서 분리한 상태로 충전하는 2구 트레이입니다. 팩을 장착한 채로 충전하려면 RBQ10 충전기를 사용하세요.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/related-products/battery">배터리 사양 →</a></div><div class="rbq-card"><img src="'+o+'" alt=""><h3 id="rbq10-charger">RBQ10 Charger<a class="header-anchor" href="#rbq10-charger" aria-label="RBQ10 Charger 링크"></a></h3><p>로봇 상단의 충전 포트에 직접 연결하는 제공 충전기입니다. 표준 AC 전원을 입력받아 배터리를 장착한 상태로 충전합니다.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/operation/charging">충전 방법 →</a></div><div class="rbq-card"><img src="'+n+'" alt=""><h3 id="docking-station">Docking Station<a class="header-anchor" href="#docking-station" aria-label="Docking Station 링크"></a></h3><p class="rbq-card-badges"><span class="rbq-badge">Dog House · Coming soon</span></p><p>RBQ가 자율적으로 도킹하여 자동 배터리 충전 및 보관이 가능한 도킹 스테이션입니다. 장시간 연속 운용 시 수동 배터리 교체 없이 운용할 수 있습니다.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/related-products/docking-station">상세 사양 →</a></div></div><h2 id="payload-cabling" tabindex="-1">페이로드 배선 <a class="header-anchor" href="#payload-cabling" aria-label="Permalink to &quot;페이로드 배선 {#payload-cabling}&quot;">​</a></h2><p>직접 만든 페이로드를 로봇의 전원·통신에 연결하는 케이블입니다. 로봇 쪽 끝은 외부 포트 패널의 MOCO 방수 커넥터에 그대로 체결되고, 반대쪽은 사용자 장비에 맞춰 씁니다. 포트별 전압·전류 한계와 핀 배열은 <a href="/RBQ/nightly/ko/manual/interface/external-port.html#user-port-pin-map">외부 포트 정보</a>에 있습니다.</p><div class="rbq-card-grid"><div class="rbq-card"><h3 id="cable-12pin">12PIN MOCO — 12V + LAN<a class="header-anchor" href="#cable-12pin" aria-label="12PIN MOCO — 12V + LAN 링크"></a></h3><p>패널 버전 2의 <code>12V/LAN</code> 포트에 연결해 <strong>12V 전원과 기가비트 이더넷</strong>을 한 가닥으로 뽑아냅니다. 전원과 네트워크가 함께 필요한 카메라·센서에 씁니다.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/interface/external-port#lan-v2">핀맵 →</a></div><div class="rbq-card"><h3 id="cable-4pin">4PIN MOCO — 48V + CAN<a class="header-anchor" href="#cable-4pin" aria-label="4PIN MOCO — 48V + CAN 링크"></a></h3><p><code>PWR-CAN</code>(패널 버전 2는 <code>PWR/CAN</code>) 포트에 연결해 <strong>배터리 전원과 CAN 통신</strong>을 함께 뽑아냅니다. CAN으로 제어하는 액추에이터·장치에 씁니다.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/interface/external-port#pwr-can">핀맵 →</a></div><div class="rbq-card"><h3 id="cable-2pin">2PIN MOCO — 48V<a class="header-anchor" href="#cable-2pin" aria-label="2PIN MOCO — 48V 링크"></a></h3><p><code>POWER</code> 포트에 연결해 <strong>배터리 전원만</strong> 뽑아냅니다. 통신이 필요 없는 부하에 씁니다.</p><a class="rbq-card-cta" href="/RBQ/nightly/ko/manual/interface/external-port#power">핀맵 →</a></div></div><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>48V 계열 두 케이블이 내보내는 전압은 <strong>배터리 전압 그대로</strong>라 잔량에 따라 42.0~58.4V 사이에서 변합니다. 정전압이 필요한 페이로드에는 컨버터를 따로 두세요. 포트별 최대 전류(<code>POWER</code> 5A · <code>PWR-CAN</code> 10A · <code>12V/LAN</code> 2~3A)를 넘지 않도록 설계해야 합니다.</p></div></div><p>커넥터를 끼우고 빼는 방법은 <a href="/RBQ/nightly/ko/manual/maintenance/connector.html">커넥터 탈부착</a>에, 포트에 전원을 넣는 방법은 <a href="/RBQ/nightly/ko/manual/interface/port-power.html">외부 포트 전원 켜기</a>에 있습니다.</p>',13)])])}const Q=h(b,[["render",u]]);export{C as __pageData,Q as default};
